import { getCurrentUser, getUserByEmail, setCurrentUser } from './mock-data';

export function isAuthenticated(): boolean {
  if (typeof window === 'undefined') return false;
  return !!getCurrentUser();
}

export function getCurrentUserRole(): 'user' | 'admin' | null {
  const user = getCurrentUser();
  return user ? user.role : null;
}

export function isAdmin(): boolean {
  return getCurrentUserRole() === 'admin';
}

export function isUser(): boolean {
  return getCurrentUserRole() === 'user';
}

export function login(email: string, password: string): { success: boolean; message: string } {
  const user = getUserByEmail(email);
  
  if (!user) {
    return { success: false, message: 'User not found' };
  }

  // Mock password validation
  if (user.password !== password) {
    return { success: false, message: 'Invalid password' };
  }

  setCurrentUser(user.id, user.role);
  return { success: true, message: 'Login successful' };
}

export function logout() {
  if (typeof window === 'undefined') return;
  localStorage.removeItem('trustline_current_user');
  localStorage.removeItem('trustline_current_role');
}
